<script setup lang="ts">
import { onMounted, reactive, ref, watch } from 'vue'
import { api } from '../api'
import NumberSettingRow from './NumberSettingRow.vue'
import ToggleSettingRow from './ToggleSettingRow.vue'
interface Settings { update: { l2_budget: number; l3_budget: number }; audit: { l2_budget: number; l3_budget: number }; dedup: { iterations: number; auto_after_update: boolean }; merge: { auto_after_update: boolean; auto_after_audit: boolean; auto_after_dedup: boolean }; chunking: { overlap_ratio: number; boundary: 'paragraph' | 'sentence'; min_chunk_chars: number; max_chunk_chars: number }; reference: { enforce_required: boolean; drop_invalid_refs: boolean } }
const props = withDefaults(defineProps<{ pending?: unknown; revision?: number }>(), { revision: 0 })
const emit = defineEmits<{ change: [value: Settings]; loaded: [value: Settings] }>()
const settings = reactive<Settings>({ update: { l2_budget: 4, l3_budget: 4 }, audit: { l2_budget: 4, l3_budget: 4 }, dedup: { iterations: 3, auto_after_update: false }, merge: { auto_after_update: false, auto_after_audit: false, auto_after_dedup: false }, chunking: { overlap_ratio: 0.1, boundary: 'paragraph', min_chunk_chars: 1200, max_chunk_chars: 4000 }, reference: { enforce_required: true, drop_invalid_refs: true } })
const loading = ref(true); const error = ref('')
function assign(next: Settings) { Object.assign(settings, next) }
async function load() { loading.value = true; error.value = ''; try { const live = await api<Settings>('/api/memory/settings'); assign((props.pending as Settings | undefined) ?? live); emit('loaded', live) } catch (cause) { error.value = cause instanceof Error ? cause.message : '设置加载失败' } finally { loading.value = false } }
onMounted(load); watch(() => props.revision, load)
function changed() { emit('change', JSON.parse(JSON.stringify(settings))) }
function patch<K extends keyof Settings>(key: K, value: Partial<Settings[K]>) { Object.assign(settings[key], value); changed() }
</script>
<template><div><header class="legacy-settings-page-header"><h1>记忆</h1><p>调整分块整理器：Update / Audit / Dedup 的 LLM 轮次、分块强度，以及引用校验的严格程度。</p></header><p v-if="error" class="error" role="alert">{{ error }}</p><p v-if="loading" class="legacy-settings-loading">加载中…</p><template v-else><section class="legacy-setting-section"><header><h2>Update 模式</h2><p>分块增量事实提取的默认 LLM 轮次；单文档覆盖在工作台中设置。</p></header><div class="legacy-setting-section-body"><NumberSettingRow title="L2 预算（每个 surface）" description="一次 L2 update 最多生成的分块数。" :value="settings.update.l2_budget" :min="1" :max="200" @change="patch('update', { l2_budget: $event })" /><NumberSettingRow title="L3 预算（每个 slot）" description="一次 L3 update 跨 7 份 L2 文档的最大分块数。" :value="settings.update.l3_budget" :min="1" :max="200" @change="patch('update', { l3_budget: $event })" /></div></section><section class="legacy-setting-section"><header><h2>Audit 模式</h2><p>根据原始证据逐行编辑的默认 LLM 轮次。</p></header><div class="legacy-setting-section-body"><NumberSettingRow title="L2 预算（每个 surface）" :value="settings.audit.l2_budget" :min="1" :max="200" @change="patch('audit', { l2_budget: $event })" /><NumberSettingRow title="L3 预算（每个 slot）" :value="settings.audit.l3_budget" :min="1" :max="200" @change="patch('audit', { l3_budget: $event })" /></div></section><section class="legacy-setting-section"><header><h2>Dedup</h2><p>对完整文档进行迭代去重；某轮没有编辑时提前停止。</p></header><div class="legacy-setting-section-body"><NumberSettingRow title="迭代次数" :value="settings.dedup.iterations" :min="1" :max="20" @change="patch('dedup', { iterations: $event })" /><ToggleSettingRow title="Update 后自动运行 Dedup" :checked="settings.dedup.auto_after_update" @change="patch('dedup', { auto_after_update: $event })" /></div></section><section class="legacy-setting-section"><header><h2>合并脚注</h2><p>不使用 LLM：合并重复引用行并重新编号，可安全重复执行。</p></header><div class="legacy-setting-section-body"><ToggleSettingRow title="Update 后自动合并" :checked="settings.merge.auto_after_update" @change="patch('merge', { auto_after_update: $event })" /><ToggleSettingRow title="Audit 后自动合并" :checked="settings.merge.auto_after_audit" @change="patch('merge', { auto_after_audit: $event })" /><ToggleSettingRow title="Dedup 后自动合并" :checked="settings.merge.auto_after_dedup" @change="patch('merge', { auto_after_dedup: $event })" /></div></section><section class="legacy-setting-section"><header><h2>分块</h2><p>控制内容拆分方式的底层选项。</p></header><div class="legacy-setting-section-body"><NumberSettingRow title="重叠比例" description="下一块携带上一块内容的比例，范围 0–0.5。" :value="settings.chunking.overlap_ratio" :min="0" :max="0.5" :step="0.05" float @change="patch('chunking', { overlap_ratio: $event })" /><div class="legacy-setting-row"><div><h3>边界</h3><p>分块器优先切分的位置。</p></div><select v-model="settings.chunking.boundary" aria-label="边界" @change="changed"><option value="paragraph">段落</option><option value="sentence">句子</option></select></div><NumberSettingRow title="最小分块字符数" description="单个分块的下限。" :value="settings.chunking.min_chunk_chars" :min="200" :max="64000" :step="100" @change="patch('chunking', { min_chunk_chars: $event })" /><NumberSettingRow title="最大分块字符数" description="单个分块的上限。" :value="settings.chunking.max_chunk_chars" :min="200" :max="64000" :step="100" @change="patch('chunking', { max_chunk_chars: $event })" /></div></section><section class="legacy-setting-section"><header><h2>引用</h2><p>事实必须如何引用其提取来源分块。</p></header><div class="legacy-setting-section-body"><ToggleSettingRow title="每条事实都必须带引用" description="丢弃未返回引用的事实。" :checked="settings.reference.enforce_required" @change="patch('reference', { enforce_required: $event })" /><ToggleSettingRow title="丢弃无效引用（而不是整条事实）" description="开启时保留事实，仅移除来源池外的引用；关闭时，任何无效引用都会拒绝事实。" :checked="settings.reference.drop_invalid_refs" @change="patch('reference', { drop_invalid_refs: $event })" /></div></section></template></div></template>
